const cards=computed(()=>en.value?[{title:'First steps',link:'getting-started',description:'Installation, tools and your first altar.'},{title:'Recipes and materials',link:'recipes',description:'Workstations, alternatives, quantities and results.'},{title:'Cooking and restaurants',link:'blocks/cooking',description:'Kitchenware, menus, the night-sparrow bell and customers.'},{title:'Companions and work',link:'entities/npc-companion',description:'Role cards, ownership, inventories and work modes.'},{title:'Combat and equipment',link:'items/weapons',description:'Danmaku, ammunition, controls and equipment.'},{title:'Explore the worlds',link:'world/gensokyo',description:'Gensokyo, the dream world and the Moon.'}]:[{title:'第一次游玩',link:'getting-started',description:'确认运行环境，准备工具，完成第一个祭坛。'},{title:'配方与材料',link:'recipes',description:'查工作台、材料替代、所需数量与产物。'},{title:'料理与餐厅',link:'blocks/cooking',description:'认识厨具、菜单本、夜雀钟与顾客点单。'},{title:'伙伴与工作',link:'entities/npc-companion',description:'角色卡、契约、背包整备与 NPC 工作模式。'},{title:'战斗与装备',link:'items/weapons',description:'武器操作、弹药、弹幕制作与装备选择。'},{title:'探索世界',link:'world/gensokyo',description:'前往幻想乡、第四槐安通道与月面。'}]);function go(){location.href=withBase(prefix.value+'catalog?search='+encodeURIComponent(search.value))}
